// Exercises the generated runtime (the committed golden, regenerated by
// tool/update_goldens.dart) against the real dartvex types. Importing it also
// proves the generated runtime compiles.
import 'dart:async';

import 'package:dartvex/dartvex.dart';
import 'package:test/test.dart';

import '../goldens/sample/runtime.dart';

void main() {
  group('typedQueryResult', () {
    String decodeStatus(dynamic raw) {
      if (raw == 'draft' || raw == 'sent') {
        return raw as String;
      }
      throw FormatException('Expected one of draft, sent, got $raw');
    }

    test('forwards hasPendingWrites and logLines on success', () {
      final result = typedQueryResult<String>(
        const QuerySuccess(
          'sent',
          logLines: <String>['log'],
          hasPendingWrites: true,
        ),
        decodeStatus,
        'messages:status',
      );

      expect(
        result,
        isA<TypedQuerySuccess<String>>()
            .having((success) => success.value, 'value', 'sent')
            .having((success) => success.hasPendingWrites, 'pending', isTrue)
            .having((success) => success.logLines, 'logLines', <String>['log']),
      );
    });

    test('turns a decode failure into a TypedQueryError', () {
      final result = typedQueryResult<String>(
        const QuerySuccess('archived', logLines: <String>['log']),
        decodeStatus,
        'messages:status',
      );

      expect(
        result,
        isA<TypedQueryError<String>>()
            .having(
              (error) => error.message,
              'message',
              allOf(
                contains('Failed to decode messages:status result'),
                contains('archived'),
              ),
            )
            .having((error) => error.data, 'data', isA<FormatException>())
            .having((error) => error.logLines, 'logLines', <String>['log']),
      );
    });

    test('maps loading and error events', () {
      expect(
        typedQueryResult<String>(
          const QueryLoading(hasPendingWrites: true),
          decodeStatus,
          'f',
        ),
        isA<TypedQueryLoading<String>>().having(
          (loading) => loading.hasPendingWrites,
          'pending',
          isTrue,
        ),
      );
      expect(
        typedQueryResult<String>(
          const QueryError('boom', data: 42),
          decodeStatus,
          'f',
        ),
        isA<TypedQueryError<String>>()
            .having((error) => error.message, 'message', 'boom')
            .having((error) => error.data, 'data', 42),
      );
    });
  });

  group('TypedConvexPaginatedQuery', () {
    test('exposes one stable stream and caches decoded snapshots', () async {
      var decodes = 0;
      final delegate = _FakePaginatedQuery(
        const ConvexPaginatedResult(
          results: <dynamic>[1, 2, 3],
          status: ConvexPaginationStatus.canLoadMore,
          isDone: false,
        ),
      );
      final query = TypedConvexPaginatedQuery<int>(delegate, (raw) {
        decodes += 1;
        return raw as int;
      });

      expect(identical(query.stream, query.stream), isTrue);
      expect(query.items, <int>[1, 2, 3]);
      expect(query.items, <int>[1, 2, 3]);
      expect(query.current.items, <int>[1, 2, 3]);
      expect(decodes, 3, reason: 'one decode per item per raw snapshot');
      expect(() => query.items.add(4), throwsUnsupportedError);

      final received = <TypedConvexPaginatedResult<int>>[];
      final subscription = query.stream.listen(received.add);
      delegate.emit(
        const ConvexPaginatedResult(
          results: <dynamic>[1, 2, 3, 4],
          status: ConvexPaginationStatus.exhausted,
          isDone: true,
        ),
      );
      await Future<void>.delayed(Duration.zero);
      expect(received.single.items, <int>[1, 2, 3, 4]);
      expect(query.items, <int>[1, 2, 3, 4]);
      expect(query.status, ConvexPaginationStatus.exhausted);
      await subscription.cancel();
    });

    test('reports undecodable items as an error snapshot', () async {
      final delegate = _FakePaginatedQuery(
        const ConvexPaginatedResult(
          results: <dynamic>[1, 'oops'],
          status: ConvexPaginationStatus.canLoadMore,
          isDone: false,
        ),
      );
      final query = TypedConvexPaginatedQuery<int>(
        delegate,
        (raw) => raw is int ? raw : throw FormatException('bad item $raw'),
      );

      final current = query.current;
      expect(current.status, ConvexPaginationStatus.error);
      expect(current.items, isEmpty);
      expect(current.error, isA<FormatException>());
      expect(query.status, ConvexPaginationStatus.error);
      expect(query.items, isEmpty);

      final received = <TypedConvexPaginatedResult<int>>[];
      final errors = <Object>[];
      final subscription = query.stream.listen(
        received.add,
        onError: errors.add,
      );
      delegate.emit(
        const ConvexPaginatedResult(
          results: <dynamic>['still bad'],
          status: ConvexPaginationStatus.exhausted,
          isDone: true,
        ),
      );
      await Future<void>.delayed(Duration.zero);
      expect(errors, isEmpty);
      expect(received.single.status, ConvexPaginationStatus.error);
      await subscription.cancel();
    });
  });
}

class _FakePaginatedQuery implements ConvexPaginatedQuery {
  _FakePaginatedQuery(this._current);

  final StreamController<ConvexPaginatedResult> _controller =
      StreamController<ConvexPaginatedResult>.broadcast(sync: true);
  ConvexPaginatedResult _current;

  void emit(ConvexPaginatedResult result) {
    _current = result;
    _controller.add(result);
  }

  @override
  Stream<ConvexPaginatedResult> get stream => _controller.stream;

  @override
  ConvexPaginatedResult get current => _current;

  @override
  ConvexPaginationStatus get status => _current.status;

  @override
  bool get isDone => _current.isDone;

  @override
  bool loadMore([int? numItems]) => false;

  @override
  void cancel() {}

  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}
